descriptor.templateCss:
.solar-card-container {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 14px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #f7d048;
  padding: 16px 22px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
  overflow: hidden;
}

.solar-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.solar-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
}

.solar-sun-icon {
  font-size: 16px;
}

.solar-live-badge {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: #64B856;
  border: 1.5px solid #64B856;
  background: rgba(100, 184, 86, 0.08);
  padding: 2px 10px;
  border-radius: 20px;
}

.solar-metric-body {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 6px 0;
}

.metric-value {
  font-size: 40px;
  font-weight: 800;
  color: #f7d048;
  line-height: 1;
}

.metric-unit {
  font-size: 20px;
  font-weight: 600;
  color: #94a3b8;
}

.solar-divider {
  width: 100%;
  height: 1px;
  background: rgba(148, 163, 184, 0.15);
  margin: 8px 0 10px 0;
}

.solar-card-footer {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
}

.footer-left .footer-label {
  font-size: 13px;
  font-weight: 500;
  color: #94a3b8;
}

.footer-left .footer-subtext {
  font-size: 12px;
  color: #556987;
  margin-top: 3px;
}

.footer-right .footer-value {
  font-size: 16px;
  font-weight: 700;
  color: #f7d048;
}

descriptor.controllerScript:
self.onInit = function() {
  self.onDataUpdated();
};

self.onDataUpdated = function() {
  var data = self.ctx.data;
  var powerVal = "44.8";
  var energyVal = "5287.3";

  if (data && data.length > 0) {
    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      if (item.data && item.data.length > 0) {
        var lastVal = item.data[item.data.length - 1][1];
        var num = parseFloat(lastVal);
        var formatted = !isNaN(num) ? num.toFixed(1) : lastVal;
        var keyName = (item.dataKey.label || item.dataKey.name || "").toLowerCase();

        if (keyName.indexOf("energy") !== -1 || keyName.indexOf("energia") !== -1 || keyName.indexOf("acumulado") !== -1 || i === 1) {
          energyVal = formatted;
        } else {
          powerVal = formatted;
        }
      }
    }
  }

  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (container) {
    var elPower = container.querySelector('#solar-power-value');
    if (elPower) elPower.textContent = powerVal;

    var elEnergy = container.querySelector('#solar-energy-value');
    if (elEnergy) elEnergy.textContent = energyVal + ' kWh';
  }
};

self.onDestroy = function() {};
